import type { ContractRecord } from "./api/contracts"
import type { ServiceRecord } from "./api/services"

// Keep template previews aligned with the contract document generated by the API.
export function getContractTemplateServices(contract: ContractRecord, catalog: ServiceRecord[]) {
  const services = contract.services.map((item) => ({
    serviceTypeId: item.serviceTypeId,
    name: catalog.find((service) => service.id === item.serviceTypeId)?.name ?? item.serviceTypeId,
    clauses: (item.clauses ?? []).map((clause) => clause.trim()).filter(Boolean),
  }))
  const insectControl = services.find((service) => service.serviceTypeId === "srv-dedetizacao")
  const rodentControl = services.find((service) => service.serviceTypeId === "srv-desratizacao")
  const merged = services.filter((service) => !["srv-dedetizacao", "srv-desratizacao"].includes(service.serviceTypeId))
  if (insectControl && rodentControl) {
    merged.push({
      serviceTypeId: "srv-controle-de-pragas",
      name: "Controle de pragas",
      clauses: [...new Set([...insectControl.clauses, ...rodentControl.clauses])],
    })
  } else {
    if (insectControl) merged.push(insectControl)
    if (rodentControl) merged.push(rodentControl)
  }
  return merged.filter((service) => service.clauses.length > 0)
}
